globalThis.emailContentByLanguage = emailContentByLanguage;

function escapeHtmlText(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

function normalizeTemplateList(value, options = {}) {
  const multiline = options.multiline === true;
  const maxLength = multiline ? 8000 : 200;
  const maxItems = Number.isInteger(options.maxItems) && options.maxItems > 0 ? options.maxItems : 500;
  const next = [];
  const seen = new Set();
  for (const item of Array.isArray(value) ? value : []) {
    let text = String(item ?? "").replace(/\r\n/g, "\n").trim();
    if (!multiline) text = text.replace(/\s+/g, " ").trim();
    if (text.length > maxLength) text = text.slice(0, maxLength).trim();
    if (!text) continue;
    const key = text.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    next.push(text);
    if (next.length >= maxItems) break;
  }
  return next;
}

const TEMPLATE_HEADER_NAMES = {
  subject: ["subject", "subjects"],
  body: ["body", "bodies"],
  reply: ["reply", "replies", "warm-up reply", "warmup reply"],
  followup: ["follow-up", "follow up", "followup", "follow-up email"],
};
const TEMPLATE_GENERIC_HEADERS = ["text", "email", "message", "template", "content"];
const TEMPLATE_HEADERS = new Set(
  TEMPLATE_GENERIC_HEADERS.concat(...Object.values(TEMPLATE_HEADER_NAMES))
);

function parseDelimited(text, delimiter) {
  const rows = [];
  let row = [];
  let cell = "";
  let quoted = false;
  const src = String(text ?? "").replace(/^\uFEFF/, "").replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  for (let index = 0; index < src.length; index += 1) {
    const char = src[index];
    if (quoted) {
      if (char === "\"") {
        if (src[index + 1] === "\"") {
          cell += "\"";
          index += 1;
        } else quoted = false;
      } else cell += char;
    } else if (char === "\"") {
      quoted = true;
    } else if (char === delimiter) {
      row.push(cell);
      cell = "";
    } else if (char === "\n") {
      row.push(cell);
      rows.push(row);
      row = [];
      cell = "";
    } else cell += char;
  }
  if (cell.length || row.length) {
    row.push(cell);
    rows.push(row);
  }
  return rows.filter((item) => item.some((value) => String(value).trim()));
}

function csvDelimiter(text) {
  let chosen = ",";
  let widest = 1;
  for (const delimiter of [",", ";", "\t"]) {
    const width = parseDelimited(text, delimiter)[0]?.length || 0;
    if (width > widest) {
      chosen = delimiter;
      widest = width;
    }
  }
  return chosen;
}

function templateColumn(header, kind) {
  const names = header.map((cell) => String(cell || "").trim().toLowerCase());
  for (const name of TEMPLATE_HEADER_NAMES[kind] || []) {
    const index = names.indexOf(name);
    if (index >= 0) return index;
  }
  for (const name of TEMPLATE_GENERIC_HEADERS) {
    const index = names.indexOf(name);
    if (index >= 0) return index;
  }
  return 0;
}

function textsFromCsv(text, kind) {
  const table = parseDelimited(text, csvDelimiter(text));
  if (!table.length) return [];
  const first = String(table[0][0] || "").trim().toLowerCase();
  const headed = TEMPLATE_HEADERS.has(first);
  if (!headed || table[0].length < 2) {
    const plain = parseDelimited(text, "\u0000").map((row) => row.join(""));
    if (headed && String(plain[0] || "").trim().toLowerCase() === first) plain.shift();
    return plain;
  }
  const column = templateColumn(table[0], kind);
  return table.slice(1).map((row) => row[column] || "");
}

function textsFromTxt(text, multiline) {
  const normalized = String(text ?? "").replace(/^\uFEFF/, "").replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  const lines = normalized.split("\n");
  if (lines.some((line) => line.trim() === "---")) {
    const chunks = [];
    let current = [];
    for (const line of lines) {
      if (line.trim() === "---") {
        const block = current.join("\n").trim();
        if (block) chunks.push(block);
        current = [];
        continue;
      }
      current.push(line);
    }
    const tail = current.join("\n").trim();
    if (tail) chunks.push(tail);
    return chunks;
  }
  if (!multiline) return lines.map((line) => line.trim()).filter(Boolean);
  const whole = normalized.trim();
  return whole ? [whole] : [];
}

function parseTemplateFileText(raw, options = {}) {
  const ext = String(options.ext || "").toLowerCase();
  const kind = String(options.kind || "");
  const multiline = options.multiline === true;
  const items = ext === "csv" ? textsFromCsv(raw, kind) : textsFromTxt(raw, multiline);
  return normalizeTemplateList(items, { multiline, maxItems: 2000 });
}

function customTemplateErrors(input) {
  if (input?.useCustomTemplates !== true) return [];
  const errors = [];
  if (!normalizeTemplateList(input.customSubjects).length) errors.push("Add at least one subject template.");
  if (!normalizeTemplateList(input.customBodies, { multiline: true }).length) errors.push("Add at least one body template.");
  return errors;
}

function applyPlaceholders(text, contact, senderName) {
  return String(text ?? "")
    .replace(/\[Name\]/g, senderName || "")
    .replace(/\[Company\]/g, contact?.company || "")
    .replace(/\[Recipient\]/g, String(contact?.name || "").trim());
}

function formatReplyText(text, senderName, contact) {
  const first = String(senderName || "").replace(/\s+/g, " ").trim().split(" ")[0] || "";
  return applyPlaceholders(text, contact, first).replace(/\{sender\}/gi, first);
}

const ATTACH_SENTENCE = /attach|附上|已附|beigefügt|anhang|संलग्न/i;

function withoutAttachSentences(text) {
  return String(text)
    .split(/\n{2,}/)
    .map((paragraph) => paragraph
      .split(/(?<=[.!?。।])\s+/)
      .filter((sentence) => sentence.trim() && !ATTACH_SENTENCE.test(sentence))
      .join(" ")
      .trim())
    .filter(Boolean)
    .join("\n\n");
}

function pickItem(list, index) {
  const chosen = Number(index);
  if (Number.isInteger(chosen) && chosen >= 0 && chosen < list.length) return list[chosen];
  return list[Math.floor(Math.random() * list.length)];
}

function personalizeEmail(language, contact, senderName, options = {}) {
  const library = globalThis.emailContentByLanguage;
  const content = library[language] || library.en;
  const recipient = contact?.name || "";
  const customSubjects = options.useCustom ? normalizeTemplateList(options.subjects) : [];
  const customBodies = options.useCustom
    ? normalizeTemplateList(options.bodies ?? options.templates, { multiline: true })
    : [];
  const useCustom = customSubjects.length > 0 && customBodies.length > 0;
  const subject = applyPlaceholders(
    pickItem(useCustom ? customSubjects : content.subjects, options.subjectIndex),
    contact,
    senderName || ""
  );
  let message = applyPlaceholders(
    pickItem(useCustom ? customBodies : content.templates, options.templateIndex),
    contact,
    senderName || ""
  );
  if (options.includeAttach === false) message = withoutAttachSentences(message);
  const greetingLine = recipient ? content.greeting + " " + recipient + "," : content.greeting + ",";
  const bodyText = useCustom ? message : greetingLine + "\n\n" + message;
  const bodyHtml = escapeHtmlText(bodyText).replace(/\n/g, "<br>");
  return { subject, bodyText, bodyHtml };
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    emailContentByLanguage,
    applyPlaceholders,
    formatReplyText,
    customTemplateErrors,
    normalizeTemplateList,
    parseTemplateFileText,
    personalizeEmail,
    withoutAttachSentences,
  };
}
